module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

reg [1:0] mul_en_out_reg;
reg [7:0] mul_a_reg;
reg [7:0] mul_b_reg;
reg [15:0] temp [0:7];
reg [15:0] sum [0:4];
reg [15:0] mul_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_en_out_reg <= 0;
    end else begin
        mul_en_out_reg <= {mul_en_out_reg[0], mul_en_in};
    end
end

assign mul_en_out = mul_en_out_reg[1];

always @(posedge clk) begin
    if (mul_en_out_reg[0]) begin
        mul_a_reg <= mul_a;
    end else begin
        mul_a_reg <= 0;
    end
end

always @(posedge clk) begin
    if (mul_en_out_reg[0]) begin
        mul_b_reg <= mul_b;
    end else begin
        mul_b_reg <= 0;
    end
end

genvar i;
generate
    for (i = 0; i < 8; i = i + 1) begin : gen_partial_products
        assign temp[i][7:0] = (mul_b_reg[i]) ? mul_a_reg : 8'h00;
    end
endgenerate

genvar j;
generate
    for (j = 0; j < 8; j = j + 1) begin : gen_partial_sums
        if (j == 0) begin
            assign sum[j][15:0] = temp[j][15:0];
        end else begin
            assign sum[j][15:0] = sum[j-1][15:0] + temp[j][15:0];
        end
    end
endgenerate

always @(posedge clk) begin
    mul_out_reg <= sum[7][15:0];
end

assign mul_out = (mul_en_out_reg[1]) ? mul_out_reg : 16'h0000;
endmodule
